def pluck(arr):
    """
    Returns the smallest even value and its index from the input array.
    If no even values exist or the array is empty, returns an empty list.
    """
    if not arr:
        return []

    min_even = None
    min_index = -1

    for i, val in enumerate(arr):
        if val % 2 == 0:
            if min_even is None or val < min_even:
                min_even = val
                min_index = i

    if min_even is None:
        return []
    else:
        return [min_even, min_index]

