def search(lst):
    """
    Returns the greatest integer x > 0 such that its frequency in lst is >= x.
    If no such integer exists, returns -1.
    """
    # Count frequencies
    freq = {}
    for num in lst:
        freq[num] = freq.get(num, 0) + 1

    # Find the greatest integer satisfying condition
    result = -1
    for num, count in freq.items():
        if count >= num and num > result:
            result = num
    return result

