def histogram(test):
    """
    Given a string representing space-separated lowercase letters, return a dictionary
    of the letter(s) with the highest frequency and their counts.
    If several letters have the same highest occurrence, return all of them.
    """
    if not test:
        return {}

    # Split the string into individual letters
    letters = test.split()
    # Count occurrences
    freq = {}
    for letter in letters:
        freq[letter] = freq.get(letter, 0) + 1

    # Find the maximum frequency
    max_count = max(freq.values())

    # Build result dictionary with letters having max frequency
    result = {letter: count for letter, count in freq.items() if count == max_count}
    return result

