        """Check if n is a prime number."""
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    # Find the largest prime in the list
    max_prime = None
    for num in lst:
        if is_prime(num):
            if max_prime is None or num > max_prime:
                max_prime = num

    # If no prime found, return 0 (though problem implies at least one prime)
    if max_prime is None:
        return 0

    # Sum the digits of the largest prime
