def maximum(arr, k):
    """
    Returns a sorted list of the k largest numbers in arr.
    If k is 0, returns an empty list.
    """
    if k == 0:
        return []
    # Get the k largest numbers (sorted descending) then sort ascending
    top_k = sorted(arr, reverse=True)[:k]
    return sorted(top_k)

