def compare_one(a, b):
    """
    Returns the larger of two values (int, float, or string representing a real number).
    Returns None if they are equal.
    Strings may use comma as decimal separator.
    """
    def to_float(x):
        """Convert a value to float for comparison."""
        if isinstance(x, str):
            # Replace comma with dot for decimal parsing
            return float(x.replace(',', '.'))
        else:
            return float(x)

    # Convert both to float for comparison
    fa = to_float(a)
    fb = to_float(b)

    # Compare
    if fa > fb:
        return a
    elif fb > fa:
        return b
    else:
        return None

