def sum_squares(lst):
    """
    This function takes a list of integers. For each entry, if its index is a multiple of 3,
    it squares the value; if its index is a multiple of 4 but not a multiple of 3, it cubes the value;
    otherwise, the value is unchanged. The function returns the sum of all resulting entries.
    """
    total = 0
    for i, val in enumerate(lst):
        if i % 3 == 0:
            total += val ** 2
        elif i % 4 == 0:
            total += val ** 3
        else:
            total += val
    return total
